package net.massa.gossip.mesh

import net.massa.gossip.mesh.ffi.MeshCoreSink as FfiSink
import net.massa.gossip.mesh.ffi.MeshKeyValue as FfiKeyValue
import net.massa.gossip.mesh.ffi.MeshNodeCore
import net.massa.gossip.mesh.ffi.MeshNodeCoreInterface
import net.massa.gossip.mesh.ffi.MeshBlobKind as FfiBlobKind

/**
 * [MeshCore] over the Rust `gossip-mobile` node (UniFFI bindings generated by
 * scripts/build-mesh-android.sh). Built only when the gossip-node checkout is
 * present; [MeshCoreFactory] finds it by name and falls back to the stub.
 *
 * The node may call the sink from inside [linkUp] and [frameIn] (closeLink of
 * a duplicate link); the sink adapter only forwards, so that is safe as long
 * as the host sink does not call back into the core synchronously.
 */
class RustMeshCore internal constructor(
    private val node: MeshNodeCoreInterface,
) : MeshCore {

    constructor() : this(MeshNodeCore())

    private val lock = Any()
    // `wipe` restarts the node empty, upstream and wanted list included:
    // remembered here so they are applied again.
    private var upstream: Pair<List<String>, Boolean>? = null
    private var wanted: Pair<List<ByteArray>, List<ByteArray>> = emptyList<ByteArray>() to emptyList()

    override fun start(dataDir: String, configJson: String, sink: MeshCoreSink) {
        node.start(dataDir, configJson, SinkAdapter(sink))
    }

    override fun stop() = node.stop()

    override fun linkUp(linkId: Int, mtu: Int) = node.linkUp(linkId, mtu)

    override fun linkDown(linkId: Int) = node.linkDown(linkId)

    override fun frameIn(linkId: Int, frame: ByteArray) = node.frameIn(linkId, frame)

    override fun sendBlob(kind: MeshBlobKind, key: ByteArray?, payload: ByteArray, localOnly: Boolean): MeshSendResult {
        val result = node.sendBlob(kind.toFfi(), key, payload, localOnly)
        return MeshSendResult(result.id, result.counter)
    }

    override fun fetch(seekers: List<ByteArray>): List<MeshKeyValue> =
        node.fetch(seekers).map { MeshKeyValue(it.key, it.value) }

    override fun fetchBulletin(cursor: String?, limit: Int): List<MeshBulletinItem> =
        node.fetchBulletin(cursor, limit).map { MeshBulletinItem(it.counter, it.data) }

    override fun getKeys(hash: ByteArray): ByteArray? = node.getKeys(hash)

    override fun setWanted(seekers: List<ByteArray>, localSeekers: List<ByteArray>) = synchronized(lock) {
        wanted = seekers to localSeekers
        node.setWanted(seekers, localSeekers)
    }

    override fun setUpstream(urls: List<String>, bridgeEnabled: Boolean) = synchronized(lock) {
        upstream = urls to bridgeEnabled
        node.setUpstream(urls, bridgeEnabled)
    }

    override fun status(): MeshCoreStatus {
        val status = node.status()
        return MeshCoreStatus(
            running = status.running,
            meshPeers = status.meshPeers,
            upstreamReachable = status.upstreamReachable,
            bridgeEnabled = status.bridgeEnabled,
            bulletinCounter = status.bulletinCounter,
            storedBlobs = status.storedBlobs,
            linksHandshaking = status.linksHandshaking,
            meshBlobs = status.meshBlobs,
            uploadPending = status.uploadPending,
            wantedEntries = status.wantedEntries,
            clockOffsetMs = status.clockOffsetMs,
        )
    }

    override fun wipe(newConfigJson: String) = synchronized(lock) {
        node.wipe(newConfigJson)
        upstream?.let { (urls, bridge) -> node.setUpstream(urls, bridge) }
        val (seekers, localSeekers) = wanted
        if (seekers.isNotEmpty() || localSeekers.isNotEmpty()) node.setWanted(seekers, localSeekers)
    }

    override fun forgetOwn(kind: MeshBlobKind, key: ByteArray): Boolean = node.forgetOwn(kind.toFfi(), key)

    private class SinkAdapter(private val sink: MeshCoreSink) : FfiSink {
        override fun sendFrame(linkId: Int, frame: ByteArray): Boolean = sink.sendFrame(linkId, frame)

        override fun closeLink(linkId: Int) = sink.closeLink(linkId)

        override fun arrival(messages: List<FfiKeyValue>, announcements: List<ByteArray>) =
            sink.arrival(messages.map { MeshKeyValue(it.key, it.value) }, announcements)
    }

    private fun MeshBlobKind.toFfi(): FfiBlobKind = when (this) {
        MeshBlobKind.MESSAGE -> FfiBlobKind.MESSAGE
        MeshBlobKind.ANNOUNCEMENT -> FfiBlobKind.ANNOUNCEMENT
        MeshBlobKind.KEYS -> FfiBlobKind.KEYS
    }
}
